from datetime import datetime, timezone

def solve(data):
    winners = {}
    for i, order in enumerate(data["orders"]):
        instant = datetime.fromisoformat(order["updated_at"].replace("Z", "+00:00")).astimezone(timezone.utc)
        key = (instant, i)
        previous = winners.get(order["order_id"])
        if previous is None or key > previous[0]:
            winners[order["order_id"]] = (key, order, i)
    chosen = {entry[2] for entry in winners.values()}
    rows = []
    for order_id in sorted(winners):
        _, order, source_index = winners[order_id]
        customer = order.get("customer") or {}
        tags = sorted({t.strip().casefold() for t in (order.get("tags") or []) if t is not None and t.strip()})
        items = order.get("items") or []
        base = {"order_id": order_id, "customer_id": customer.get("id"), "source_index": source_index, "tags": tags}
        if not items:
            rows.append({**base, "item_index": None, "sku": None, "qty": None, "price": None, "price_state": "no_item"})
        for item_index, item in enumerate(items):
            state = "absent" if "price" not in item else ("null" if item["price"] is None else "value")
            rows.append({**base, "item_index": item_index, "sku": item.get("sku"), "qty": item.get("qty", 1), "price": item.get("price"), "price_state": state})
    return {"rows": rows, "discarded_source_indices": [i for i in range(len(data["orders"])) if i not in chosen]}

