from decimal import Decimal, localcontext, ROUND_HALF_UP

def solve(data):
    units = {"USD": Decimal("0.01"), "JPY": Decimal("1")}
    scales = {"USD": 2, "JPY": 0}
    with localcontext() as ctx:
        ctx.prec = 50
        invoices = {i["invoice_id"]: i for i in data["invoices"]}
        paid = {i: Decimal(0) for i in invoices}
        orphans = []
        for p in data["payments"]:
            if p["state"] != "settled":
                continue
            invoice = invoices.get(p["invoice_id"])
            if invoice is None or invoice["currency"] != p["currency"]:
                orphans.append(p["payment_id"])
                continue
            paid[p["invoice_id"]] += Decimal(p["amount"]).quantize(units[p["currency"]], rounding=ROUND_HALF_UP)
        rows = []
        for invoice_id in sorted(invoices):
            inv = invoices[invoice_id]
            currency = inv["currency"]
            unit = units[currency]
            due = sum(((Decimal(line["qty"]) * Decimal(line["unit_price"])).quantize(unit, rounding=ROUND_HALF_UP) for line in inv["lines"]), Decimal(0))
            received = paid[invoice_id]
            delta = received - due
            status = "settled" if abs(delta) <= unit else ("underpaid" if delta < 0 else "overpaid")
            def formatted(value):
                return format(abs(value) if value == 0 else value, f".{scales[currency]}f")
            rows.append({"invoice_id": invoice_id, "currency": currency, "due": formatted(due), "paid": formatted(received), "delta": formatted(delta), "status": status})
        return {"rows": rows, "orphan_payment_ids": sorted(orphans)}

