def solve(data):
    result = {"items": [], "requests": [], "waits": [], "outcome": None}
    seen_ids, completed_tokens = set(), set()
    token = data["start_token"]
    while True:
        script = data["responses"].get(token, [])
        for attempt in range(1, data["max_retries"] + 2):
            if attempt > len(script):
                result["outcome"] = "missing_response"
                return result
            response = script[attempt - 1]
            status = response["status"]
            result["requests"].append({"token": token, "attempt": attempt, "status": status})
            if status == 200:
                for item in response["items"]:
                    if item["id"] not in seen_ids:
                        seen_ids.add(item["id"])
                        result["items"].append(dict(item))
                completed_tokens.add(token)
                next_token = response["next_token"]
                if next_token is None:
                    result["outcome"] = "complete"
                    return result
                if next_token in completed_tokens:
                    result["outcome"] = "cursor_cycle"
                    return result
                token = next_token
                break
            if status not in (429, 503) or attempt > data["max_retries"]:
                result["outcome"] = f"http_{status}"
                return result
            delay = min(data["max_delay"], max(data["base_delay"] * 2 ** (attempt - 1), response.get("retry_after", 0)))
            result["waits"].append({"token": token, "after_attempt": attempt, "seconds": delay})

