from datetime import datetime, timezone
from collections import defaultdict

def solve(data):
    def parse(value):
        return datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(timezone.utc)
    jobs = [(j["resource"], parse(j["start"]), None if j["end"] is None else parse(j["end"])) for j in data["jobs"]]
    rows = []
    for window in sorted(data["windows"], key=lambda w: w["window_id"]):
        ws, we = parse(window["start"]), parse(window["end"])
        for resource in sorted(data["resources"]):
            changes = defaultdict(int)
            job_seconds = 0
            for name, start, end in jobs:
                if name != resource:
                    continue
                left, right = max(start, ws), min(end if end is not None else we, we)
                if left < right:
                    job_seconds += int((right - left).total_seconds())
                    changes[left] += 1
                    changes[right] -= 1
            active = covered = peak = 0
            previous = None
            for point in sorted(changes):
                if previous is not None and point > previous and active > 0:
                    covered += int((point - previous).total_seconds())
                    peak = max(peak, active)
                active += changes[point]
                previous = point
            rows.append({"window_id": window["window_id"], "resource": resource, "covered_seconds": covered, "job_seconds": job_seconds, "peak_concurrency": peak})
    return {"rows": rows}

