solutionCode:
def solve(data):
    state = {}
    ignored, rejected = [], []
    for index, event in enumerate(data["events"]):
        key, version, op = event["key"], event["version"], event["op"]
        previous = state.get(key)
        if previous is not None and version <= previous["version"]:
            ignored.append(index)
            continue
        if op == "patch" and (previous is None or previous["deleted"]):
            rejected.append(index)
            continue
        if op == "delete":
            state[key] = {"version": version, "deleted": True, "fields": {}}
        elif op == "upsert":
            state[key] = {"version": version, "deleted": False, "fields": dict(event["fields"])}
        else:
            state[key] = {"version": version, "deleted": False, "fields": {**previous["fields"], **event["fields"]}}
    rows, tombstones = [], []
    for key in sorted(state):
        entry = state[key]
        if entry["deleted"]:
            tombstones.append({"key": key, "version": entry["version"]})
        else:
            rows.append({"key": key, "version": entry["version"], "fields": entry["fields"]})
    return {"rows": rows, "tombstones": tombstones, "ignored_indices": ignored, "rejected_patch_indices": rejected}

