def solve(data):
    # Kahn + a min-heap gives deterministic runnable order.
    # Strongly connected components distinguish cycles from blocked tasks.
    return {"order": [], "cycles": [], "blocked": []}

solutionCode:
import heapq

def solve(data):
    dependencies = {t["id"]: set(t["requires"]) for t in data["tasks"]}
    outgoing = {task: set() for task in dependencies}
    for task, required in dependencies.items():
        for dependency in required:
            outgoing[dependency].add(task)
    indegree = {task: len(required) for task, required in dependencies.items()}
    ready = [task for task, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        task = heapq.heappop(ready)
        order.append(task)
        for target in outgoing[task]:
            indegree[target] -= 1
            if indegree[target] == 0:
                heapq.heappush(ready, target)
    index, lowlink, stack, on_stack, components = {}, {}, [], set(), []
    def visit(node):
        index[node] = lowlink[node] = len(index)
        stack.append(node)
        on_stack.add(node)
        for target in sorted(outgoing[node]):
            if target not in index:
                visit(target)
                lowlink[node] = min(lowlink[node], lowlink[target])
            elif target in on_stack:
                lowlink[node] = min(lowlink[node], index[target])
        if lowlink[node] == index[node]:
            component = []
            while True:
                member = stack.pop()
                on_stack.remove(member)
                component.append(member)
                if member == node:
                    break
            components.append(sorted(component))
    for node in sorted(outgoing):
        if node not in index:
            visit(node)
    cycles = sorted(component for component in components if len(component) > 1 or component[0] in outgoing[component[0]])
    cyclic = {node for component in cycles for node in component}
    executed = set(order)
    return {"order": order, "cycles": cycles, "blocked": sorted(set(outgoing) - executed - cyclic)}

