import heapq

def solve(data):
    counts, totals, snapshots = {}, {}, []
    checkpoints = set(data["checkpoints"])
    def snapshot(n):
        groups = []
        for group in sorted(counts):
            candidates = ((item, count) for item, count in counts[group].items() if count > 0)
            best = heapq.nsmallest(data["k"], candidates, key=lambda pair: (-pair[1], pair[0]))
            groups.append({"group": group, "total_count": totals[group], "top": [{"item": item, "count": count} for item, count in best]})
        snapshots.append({"after_event_count": n, "groups": groups})
    if 0 in checkpoints:
        snapshot(0)
    for n, event in enumerate(data["events"], 1):
        group, item = event["group"], event["item"]
        bucket = counts.setdefault(group, {})
        bucket[item] = bucket.get(item, 0) + event["delta"]
        totals[group] = totals.get(group, 0) + event["delta"]
        if n in checkpoints:
            snapshot(n)
    return {"snapshots": snapshots}

