import csv
import io
import re

def solve(data):
    reader = csv.reader(io.StringIO(data["csv"].removeprefix("\ufeff"), newline=""))
    next(reader)
    rows, errors, duplicates, seen, totals = [], [], [], set(), {}
    for record, fields in enumerate(reader, 1):
        diagnostic = {"record": record, "line_end": reader.line_num}
        reason = None
        if len(fields) != 4:
            reason = "column_count"
        else:
            event_id, account, amount, notes = fields
            event_id, account, amount = event_id.strip(), account.strip().casefold(), amount.strip()
            if not event_id:
                reason = "event_id"
            elif not account:
                reason = "account"
            elif re.fullmatch(r"[+-]?[0-9]+(?:\.[0-9]{1,2})?", amount) is None:
                reason = "amount"
        if reason is not None:
            errors.append({**diagnostic, "reason": reason})
            continue
        if event_id in seen:
            duplicates.append({**diagnostic, "event_id": event_id})
            continue
        sign = -1 if amount.startswith("-") else 1
        digits = amount.lstrip("+-")
        whole, dot, fraction = digits.partition(".")
        cents = sign * (int(whole) * 100 + int((fraction + "00")[:2]))
        seen.add(event_id)
        rows.append({"event_id": event_id, "account": account, "cents": cents, "notes": notes})
        totals[account] = totals.get(account, 0) + cents
    return {"rows": rows, "totals": [{"account": account, "cents": totals[account]} for account in sorted(totals)], "errors": errors, "duplicates": duplicates}

