import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

def solve(data):
    def normalize_id(value):
        value = str(value).strip()
        return str(int(value)) if re.fullmatch(r"[0-9]+", value) else value
    def normalize_active(value):
        return value.strip().lower() == "true" if isinstance(value, str) else value
    def normalize_balance(value):
        if value is None:
            return None
        with localcontext() as ctx:
            ctx.prec = 40
            amount = Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            return format(abs(amount) if amount == 0 else amount, ".2f")
    def select(rows):
        winners = {}
        for index, row in enumerate(rows):
            key = normalize_id(row["id"])
            rank = (row["revision"], index)
            if key not in winners or rank > winners[key][0]:
                winners[key] = (rank, {"revision": row["revision"], "active": normalize_active(row["active"]), "balance": normalize_balance(row["balance"])})
        selected = {entry[0][1] for entry in winners.values()}
        return {key: entry[1] for key, entry in winners.items()}, [i for i in range(len(rows)) if i not in selected]
    left, discarded_left = select(data["left"])
    right, discarded_right = select(data["right"])
    rows = []
    for key in sorted(set(left) | set(right)):
        l, r = left.get(key), right.get(key)
        if l is None:
            status, differences = "right_only", []
        elif r is None:
            status, differences = "left_only", []
        else:
            differences = [field for field in ("active", "balance") if l[field] != r[field]]
            status = "mismatch" if differences else "match"
        rows.append({"id": key, "status": status, "differences": differences, "left": l, "right": r})
    return {"rows": rows, "discarded_left": discarded_left, "discarded_right": discarded_right}

